function buildAutoPhraseFallbacks(){
  const result={};
  for(const lang of Object.keys(core||{})){
    const pairs=[];
    const add=(obj)=>{for(const k of Object.keys(obj||{})){const target=obj[k],source=EN?.[k];if(typeof source==='string'&&typeof target==='string'&&source!==target&&source.length>=2&&target.length>=2)pairs.push([source,target]);}};
    add(core[lang]); add(EXTRA?.[lang]); add(EXTRA_CLIENTS?.[lang]); add(EXTRA2?.[lang]); add(SMART?.[lang]); add(UI_EXTRA?.[lang]);
    const uniq=new Map(); for(const [a,b] of pairs) if(!uniq.has(a)) uniq.set(a,b);
    result[lang]=[...uniq.entries()].sort((a,b)=>b[0].length-a[0].length);
  }
  return result;
}
let AUTO_PHRASE_FALLBACKS=null;
let AUTO_WORD_MAPS=null;
function buildAutoWordMaps(){
  const result={};
  for(const lang of Object.keys(core||{})){
    const counts={};
    const add=(obj)=>{for(const k of Object.keys(obj||{})){const a=EN?.[k]??UI_AUDIT_EN?.[k],b=obj[k];if(typeof a!=='string'||typeof b!=='string'||a===b)continue;const aw=a.match(/[\\p{L}]+/gu)||[],bw=b.match(/[\\p{L}]+/gu)||[];if(aw.length!==bw.length)continue;for(let i=0;i<aw.length;i++){const s=aw[i].toLowerCase(),t=bw[i];counts[s] ||= {};counts[s][t]=(counts[s][t]||0)+1;}}};
    add(core[lang]);add(EXTRA?.[lang]);add(EXTRA_CLIENTS?.[lang]);add(EXTRA2?.[lang]);add(SMART?.[lang]);add(UI_EXTRA?.[lang]);
    result[lang]={};for(const s of Object.keys(counts)){const best=Object.entries(counts[s]).sort((a,b)=>b[1]-a[1])[0];if(best&&s.length>2)result[lang][s]=best[0];}
  }
  return result;
}
function autoTranslateWords(value,language){
  if(typeof value!=='string'||language==='English')return value;
  AUTO_WORD_MAPS ||= buildAutoWordMaps();
  const map=AUTO_WORD_MAPS[language]||{};
  return value.replace(/[\\p{L}]+/gu,w=>map[w.toLowerCase()]||w);
}
function autoTranslatePhrase(value,language){
  if(typeof value!=='string'||language==='English')return value;
  AUTO_PHRASE_FALLBACKS ||= buildAutoPhraseFallbacks();
  value=autoTranslateWords(value,language);
  let out=value;
  for(const [from,to] of (AUTO_PHRASE_FALLBACKS[language]||[])){
    if(from.length<3)continue;
    out=out.split(from).join(to);
  }
  return out;
}
function translateFallbackValue(value,key,language){
  value=autoTranslatePhrase(value,language);
  if(SETTINGS_UI_KEYS[key]!==undefined){const full=FULL_UI_FALLBACKS[language];if(full&&full[SETTINGS_UI_KEYS[key]]!==undefined)return full[SETTINGS_UI_KEYS[key]];}
  const full=FULL_UI_FALLBACKS[language];
  if(full&&full[value]!==undefined)return full[value];
  const map=LOCALIZED_FALLBACKS[language];
  if(map&&map[key]!==undefined)return map[key];
  const phrase=PHRASE_FALLBACKS[language];
  if(phrase&&phrase[value]!==undefined)return phrase[value];
  return value;
}
function resolveLanguage(language){
  const raw=String(language||'English').trim();
  if(core[raw]) return raw;
  const normalized=raw.replace('_','-').toLowerCase();
  return LANGUAGE_ALIASES[normalized]||LANGUAGE_ALIASES[normalized.split('-')[0]]||'English';
}

export function createTranslator(language){
  const resolved=resolveLanguage(language);
  const dict=CORE_FULL[resolved]||core[resolved]||EN;
  
  return key=>{const explicit=dict[key]??EXTRA[resolved]?.[key]??EXTRA_CLIENTS[resolved]?.[key]??EXTRA2[resolved]?.[key]??SMART_GAP_PATCH[resolved]?.[key]??SMART[resolved]?.[key]??CORE_GAP_PATCH[resolved]?.[key]??PREMIUM_PATCH[resolved]?.[key]??TRIAL_PATCH[resolved]?.[key]??SETTINGS_PATCH[resolved]?.[key]??REFERRAL_PATCH[resolved]?.[key]??UI_PATCH[resolved]?.[key]??UI_EXTRA[resolved]?.[key]??UI_AUDIT_EN[key];if(explicit!==undefined){const english=localizedEnglishValue(key);if(explicit===english){const translated=translateFallbackValue(explicit,key,resolved);if(translated!==explicit)return translated;}return explicit;}const english=localizedEnglishValue(key);if(english!==undefined){const translated=translateFallbackValue(english,key,resolved);if(translated!==english)return translated;return english;}return key;};
}
